        # Has separator: output width = left region width = sep_col
        out_width = sep_col
        right_offset = sep_col + 1
    else:
        # No separator: split evenly
        out_width = n_cols // 2
        right_offset = out_width

    result = []
    for r in range(n_rows):
        row = []
        for c in range(out_width):
            left_val = grid[r][c]
            right_val = grid[r][right_offset + c]
