def transform(grid):
    n_rows = len(grid)
    if n_rows == 0:
        return []
    n_cols = len(grid[0])

    # Find separator column
    sep_col = -1
    for c in range(n_cols):
        val = grid[0][c]
        if val != 0:
            if all(grid[r][c] == val for r in range(n_rows)):
                sep_col = c
                break

    # Calculate output width
    if sep_col > 0:
        out_width = sep_col
        right_offset = sep_col + 1
    else:
        out_width = max(n_cols // 2, 1)
        right_offset = out_width if n_cols >= 2 else 0

    # Generate output
    result = [[0] * out_width for _ in range(n_rows)]
    for r in range(n_rows):
        for c in range(out_width):
            left_val = grid[r][c] if c < n_cols else 0
            right_val = grid[r][right_offset + c] if right_offset + c < n_cols else 0
            if left_val != 0 and right_val != 0:
                result[r][c] = 2

    return result
